#include <cmath>
#include <iostream>
using namespace std;

int get_gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    int numerator, denominator, max_limit;
    cin >> numerator >> denominator >> max_limit;
    int gcd_value = get_gcd(numerator, denominator);
    numerator /= gcd_value;
    denominator /= gcd_value;
    if (max_limit >= denominator) {
        cout << numerator << "/" << denominator << "\n";
    } else {
        long double ratio = (long double)numerator / denominator;
        long double min_difference = ratio;
        int best_num = 0, best_den = 1;
        for (int i = 1; i <= max_limit; ++i) {
            long double scaled = i * ratio;
            long double floor_scaled = floor(scaled);
            long double diff1 = abs(floor_scaled / i - ratio);
            long double diff2 = abs((floor_scaled + 1) / i - ratio);
            if (min_difference > diff1 || min_difference > diff2) {
                if (diff1 > diff2) {
                    best_num = floor_scaled + 1;
                } else {
                    best_num = floor_scaled;
                }
                best_den = i;
                min_difference = min(diff1, diff2);
            }
        }
        cout << best_num << "/" << best_den;
    }
    return 0;
}
